import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"快速鍵設定","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 全域（Global）","slug":"_1-全域-global","link":"#_1-全域-global","children":[{"level":3,"title":"全域快速鍵分組","slug":"全域快速鍵分組","link":"#全域快速鍵分組","children":[]},{"level":3,"title":"功能按鍵分組","slug":"功能按鍵分組","link":"#功能按鍵分組","children":[]},{"level":3,"title":"快速導覽滑鼠觸發分組","slug":"快速導覽滑鼠觸發分組","link":"#快速導覽滑鼠觸發分組","children":[]},{"level":3,"title":"錄製快速鍵","slug":"錄製快速鍵","link":"#錄製快速鍵","children":[]},{"level":3,"title":"我的最愛專屬快速鍵","slug":"我的最愛專屬快速鍵","link":"#我的最愛專屬快速鍵","children":[]}]},{"level":2,"title":"2. 外掛模組動作（Plugin Actions）","slug":"_2-外掛模組動作-plugin-actions","link":"#_2-外掛模組動作-plugin-actions","children":[]},{"level":2,"title":"3. 程序黑名單（Process Blacklist）","slug":"_3-程序黑名單-process-blacklist","link":"#_3-程序黑名單-process-blacklist","children":[]}],"relativePath":"zh-HK/user-guide/settings/hotkeys-page.md","filePath":"zh-HK/user-guide/settings/hotkeys-page.md","lastUpdated":1791112464000}'),s={name:"zh-HK/user-guide/settings/hotkeys-page.md"};function i(n,o,a,c,d,g){return t(),l("div",null,[...o[0]||(o[0]=[r('<h1 id="快速鍵設定" tabindex="-1">快速鍵設定 <a class="header-anchor" href="#快速鍵設定" aria-label="Permalink to &quot;快速鍵設定&quot;">​</a></h1><p>快速鍵設定頁面集中管理 Lertaro 的所有全域呼出按鍵、應用程式內導覽快速鍵、外掛模組動作快捷方式以及前景程序過濾規則。頁面頂部包含三個標籤頁：<strong>全域</strong>、<strong>外掛模組動作</strong>與<strong>程序黑名單</strong>。</p><h2 id="_1-全域-global" tabindex="-1">1. 全域（Global） <a class="header-anchor" href="#_1-全域-global" aria-label="Permalink to &quot;1. 全域（Global）&quot;">​</a></h2><h3 id="全域快速鍵分組" tabindex="-1">全域快速鍵分組 <a class="header-anchor" href="#全域快速鍵分組" aria-label="Permalink to &quot;全域快速鍵分組&quot;">​</a></h3><ul><li><strong>顯示/隱藏快速搜尋</strong>：專屬按鍵錄製框。支援錄製為<strong>單鍵雙擊模式</strong>（預設雙擊 <code>Ctrl</code>，亦可設為雙擊 <code>Alt</code> 或 <code>Shift</code>），或錄製為<strong>常規組合鍵</strong>（如 <code>Alt+Space</code>）。</li><li><strong>預設開啟完整面板</strong>：核取方塊（預設關閉）。開啟後，全域呼出快速鍵會改為開啟主視窗，而不是快速視窗。首次呼出時只將視窗置於前景並聚焦一次；視窗已顯示但未啟用時再次按下會重新啟用，視窗已啟用時再次按下預設會返回快速視窗，僅在啟用「再次按下快速鍵時關閉完整視窗」時才會直接關閉。視窗不會自動保持置頂。</li><li><strong>全螢幕應用程式聚焦時仍然回應</strong>：核取方塊（預設關閉）。開啟後，即使前景有獨占全螢幕程式（如全螢幕遊戲或影片），Lertaro 依然會回應快速鍵呼出搜尋框；保持關閉則自動放行按鍵不搶佔焦點。</li><li><strong>快速跳轉（Quick Jump）</strong>：預設 <code>Ctrl+G</code>。在各類檔案對話方塊中按下即可直接跳轉到最近在檔案管理器中瀏覽過的目錄。</li><li><strong>快速導覽選單</strong>：預設不分配快速鍵。可為它指定一個可選的全域快速鍵來開啟級聯式選單。在桌面或普通應用程式中呼出時使用桌面情境；在檔案總管和原生檔案對話方塊中呼出時使用目前視窗情境。即使普通前景保護會抑制全域快速鍵，檔案管理器和檔案對話方塊仍會放行。</li></ul><h3 id="功能按鍵分組" tabindex="-1">功能按鍵分組 <a class="header-anchor" href="#功能按鍵分組" aria-label="Permalink to &quot;功能按鍵分組&quot;">​</a></h3><p>頁面提供了一系列獨立的按鍵錄製控制項，支援任意單鍵或組合鍵錄製：</p><ul><li><strong>選取下一項 / 上一項</strong>：預設 <code>Ctrl+N</code> / <code>Ctrl+P</code>（與方向鍵 <code>↓</code> / <code>↑</code> 等效）。</li><li><strong>跳轉結果修飾鍵</strong>：預設 <code>Ctrl</code>，配合數字鍵 <code>1</code>–<code>9</code> 即可在快速視窗中直達前 9 項結果。</li><li><strong>開啟動作選單</strong>：預設 <code>Ctrl+O</code>（與方向鍵 <code>→</code> 等效）。兩個按鍵都適用於快速視窗與<strong>檔案對話方塊以外</strong>的內嵌卡片；主視窗則改用按一下滑鼠右鍵或 <code>Apps</code> 鍵開啟同一個選單。</li><li><strong>從選取項補全搜尋詞</strong>：預設 <code>Ctrl+Tab</code>。</li><li><strong>QuickLook 即時預覽</strong>：預設 <code>Alt+P</code>。</li><li><strong>上/下一條關鍵字歷程</strong>：預設 <code>Alt+Up</code> / <code>Alt+Down</code>。</li><li><strong>刪除當前關鍵字歷程</strong>：預設 <code>Ctrl+Delete</code>。</li><li><strong>開啟完整搜尋主視窗</strong>：預設 <code>Ctrl+F</code>。</li><li><strong>開啟傳送視窗（LocalSend）</strong>：預設 <code>Ctrl+S</code>。</li><li><strong>保持視窗不消失（釘住）</strong>：預設 <code>Ctrl+T</code>。</li><li><strong>呼出/關閉快速面板</strong>：預設 <code>Ctrl+F2</code>。</li></ul><h3 id="快速導覽滑鼠觸發分組" tabindex="-1">快速導覽滑鼠觸發分組 <a class="header-anchor" href="#快速導覽滑鼠觸發分組" aria-label="Permalink to &quot;快速導覽滑鼠觸發分組&quot;">​</a></h3><ul><li><strong>在空白處按兩下左鍵</strong>：核取方塊（<strong>預設關閉</strong>）。在桌面或檔案總管空白處按兩下快顯快速導覽選單。</li><li><strong>在空白處按一下中鍵</strong>：核取方塊（預設開啟）。在桌面、檔案總管或檔案選取對話方塊中按一下滑鼠中鍵快顯快速導覽選單。</li></ul><p>只有桌面與檔案總管支援按兩下左鍵這種觸發方式；第三方檔案管理器只接受滑鼠中鍵。滑鼠游標停留在 Lertaro 自己的卡片上時，兩種觸發都會跳過；而即使黑名單或全螢幕一般會讓全域觸發靜默，檔案管理器與對話方塊中的兩種觸發仍然照常有效。</p><h3 id="錄製快速鍵" tabindex="-1">錄製快速鍵 <a class="header-anchor" href="#錄製快速鍵" aria-label="Permalink to &quot;錄製快速鍵&quot;">​</a></h3><p>每一次按鍵都會進入錄製框而不是後方的應用程式，因此錄製框本身也有自己的一套手勢：</p><ul><li><strong><code>Escape</code></strong>：取消錄製並清除數值。沒有「放棄並還原」這回事，一按下錄製框就已經是空的。</li><li><strong><code>✕</code></strong>：清空錄製框；<strong><code>↺</code></strong>：還原該列的出廠預設值。兩者同一時刻只會顯示其中一個：已綁定組合鍵時顯示清空，內容為空時顯示還原。</li><li><strong>單獨的修飾鍵</strong>（<code>Ctrl</code>、<code>Alt</code>、<code>Shift</code>）只對本身就能代表某個意義的列開放，也就是呼出快速鍵（會變成雙擊模式）與跳轉修飾鍵。在一般的組合鍵列上，按下並放開單獨的修飾鍵會<strong>清空</strong>該列，而不會儲存一個永遠無法觸發的值。</li><li><strong>Windows 保留的組合鍵</strong>（<code>Win+E</code>、<code>Win+D</code>……）會被拒絕：數值會被強制轉為空值，因此錄製框只是變為空白。</li><li>**不做衝突檢測。**兩列可以綁定相同的組合鍵而且完全不會警告你；只有我的最愛項目的快速鍵會回報重複或遭系統拒絕的組合，而且要等你套用之後才會提示。</li></ul><h3 id="我的最愛專屬快速鍵" tabindex="-1">我的最愛專屬快速鍵 <a class="header-anchor" href="#我的最愛專屬快速鍵" aria-label="Permalink to &quot;我的最愛專屬快速鍵&quot;">​</a></h3><p>每個我的最愛項目（<a href="./favorites.html"><strong>設定 → 我的最愛</strong></a>）都可以帶上自己的<strong>作業系統層級全域</strong>快速鍵，即使 Lertaro 沒有任何視窗開啟也照常有效，並會讓前景的檔案管理器跳轉到該資料夾。與上方的錄製列不同，它必須包含修飾鍵、不接受單獨的修飾鍵，而且無法使用 <code>F12</code>。</p><h2 id="_2-外掛模組動作-plugin-actions" tabindex="-1">2. 外掛模組動作（Plugin Actions） <a class="header-anchor" href="#_2-外掛模組動作-plugin-actions" aria-label="Permalink to &quot;2. 外掛模組動作（Plugin Actions）&quot;">​</a></h2><p>各外掛模組註冊的專屬動作快速鍵（例如內建的檔案操作：複製路徑 <code>Ctrl+Shift+C</code>、複製名稱 <code>Shift+C</code>、剪下 <code>Ctrl+X</code>、複製 <code>Ctrl+C</code>、貼上 <code>Ctrl+V</code>、刪除 <code>Delete</code>、徹底刪除 <code>Shift+Delete</code> 等）均匯集於此。</p><ul><li><strong>分組檢視</strong>：按註冊動作的來源外掛模組清晰分組。</li><li><strong>獨立重錄</strong>：每個動作均配有專屬的按鍵錄製框，按一下即可按下新按鍵進行覆蓋綁定。</li></ul><h2 id="_3-程序黑名單-process-blacklist" tabindex="-1">3. 程序黑名單（Process Blacklist） <a class="header-anchor" href="#_3-程序黑名單-process-blacklist" aria-label="Permalink to &quot;3. 程序黑名單（Process Blacklist）&quot;">​</a></h2><p>用於設定特定前景應用程式的無訊息放行機制。當黑名單中的程式處於系統前景聚焦狀態時，Lertaro 會完全放行所有全域快速鍵與滑鼠觸發手勢，絕不進行攔截。</p><ul><li><strong>不區分大小寫</strong>：新增 <code>game.exe</code> 或 <code>game</code> 均可生效。</li><li><strong>單筆新增</strong>：在單筆輸入框中輸入程序名稱，按一下<strong>新增程序</strong>按鈕。</li><li><strong>批次管理</strong>：支援按一下<strong>產生文字</strong>將當前黑名單匯出為多行文字，或在多行文字方塊中直接貼上編輯後按一下<strong>套用到列表</strong>進行一鍵批次匯入。</li><li><strong>檔案對話方塊安全豁免</strong>：即使某個程式處於黑名單中，當它彈出系統檔案選取對話方塊時，Lertaro 的內嵌搜尋與滑鼠快速導覽依然會被安全放行，確保檔案選取效率不受影響。</li></ul>',22)])])}const p=e(s,[["render",i]]);export{u as __pageData,p as default};
